func And(predicates ...predicate.ReleaseQualificationDecision) predicate.ReleaseQualificationDecision {
	return predicate.ReleaseQualificationDecision(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ReleaseQualificationDecision) predicate.ReleaseQualificationDecision {
	return predicate.ReleaseQualificationDecision(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ReleaseQualificationDecision) predicate.ReleaseQualificationDecision {
	return predicate.ReleaseQualificationDecision(sql.NotPredicates(p))
}
